// Read the incoming webhook request
const request = $json.body ?? $json;

const system = String(request.system ?? "").toUpperCase();
const action = String(request.action ?? "").toUpperCase();
const payload = request.payload ?? {};

let statusCode = 200;
let response = {};

switch (`${system}:${action}`) {

  // 1. HRIS - Create Employee
  case "HRIS:CREATE_EMPLOYEE":
    response = {
      hrEmployeeId: "EMP-88410",
      status: "ACTIVE_ONBOARDING",
      system: "BambooHR Simulated API",
      employeeName: payload.employeeName,
      email: payload.email
    };
    break;

  // 2. IDP - Provision User
  case "IDP:PROVISION_USER":
    response = {
      idpUserId: "usr_okta_992144",
      corporateEmail: payload.email,
      status: "PROVISIONED_MFA_ENROLLED",
      system: "Okta Simulated API"
    };
    break;

  // 3. ASSET - Create Hardware Requisition
  case "ASSET:CREATE_REQUISITION":
    response = {
      ticketId: "JIRA-ASSET-4412",
      status: "DISPATCH_QUEUED",
      system: "Jira Assets Simulated API",
      employeeId: payload.employeeId
    };
    break;

  // 4. SLACK - Welcome Announcement
  case "SLACK:ANNOUNCEMENT":
    response = {
      ok: true,
      channel: payload.channel ?? "general-announcements",
      ts: "1728994800.001",
      message: "Welcome announcement posted successfully."
    };
    break;

  // 5. HRIS - Rollback
  case "HRIS:ROLLBACK":
    response = {
      success: true,
      system: "HRIS",
      employeeId: payload.employeeId,
      message: "Employee record deactivated successfully."
    };
    break;

  // 6. IDP - Rollback
  case "IDP:ROLLBACK":
    response = {
      success: true,
      system: "IDP",
      idpUserId: payload.idpUserId,
      message: "Identity account access revoked successfully."
    };
    break;

  // 7. ASSET - Rollback
  case "ASSET:ROLLBACK":
    response = {
      success: true,
      system: "ASSET",
      ticketId: payload.ticketId,
      message: "Asset requisition cancelled successfully."
    };
    break;

  default:
    statusCode = 404;
    response = {
      success: false,
      error: "Unknown system or action",
      receivedSystem: system,
      receivedAction: action
    };
}

return {
  json: {
    statusCode,
    body: response
  }
};
